import{_ as d}from"./chunks/home.pc.ko.BuJHOLWU.js";import{_ as t,o as e,c,a5 as r}from"./chunks/framework.BjM_ivYE.js";const a="/RBQ/images/app/home-dock-scan.pc.ko.png",i="/RBQ/images/app/home-dock-view.pc.ko.png",l="/RBQ/images/app/home-dock-view-off.pc.ko.png",b=JSON.parse('{"title":"카메라·비전","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/camera-vision.md","filePath":"ko/manual/gui/camera-vision.md","lastUpdated":1790655143000}'),n={name:"ko/manual/gui/camera-vision.md"};function s(p,o,g,h,m,u){return e(),c("div",null,[...o[0]||(o[0]=[r('<h1 id="카메라·비전" tabindex="-1">카메라·비전 <a class="header-anchor" href="#카메라·비전" aria-label="Permalink to &quot;카메라·비전&quot;">​</a></h1><p>제어 홈의 가운데가 뷰포트입니다. 여기에 로봇의 실시간 3D 자세나 카메라 영상 중 하나가 나오고, 탭 이동(P2G)과 비전 오버레이도 이 화면에서 다룹니다.</p><p><img src="'+d+'" alt="뷰포트가 있는 제어 홈"></p><h2 id="뷰포트-소스-전환" tabindex="-1">뷰포트 소스 전환 <a class="header-anchor" href="#뷰포트-소스-전환" aria-label="Permalink to &quot;뷰포트 소스 전환&quot;">​</a></h2><p>뷰포트 상단 가운데의 소스 이름을 탭하면 소스 목록이 열립니다. 로봇이 실제로 보고한 카메라의 소스만 올라오므로, 카메라가 적은 로봇에서는 목록이 짧습니다.</p><table tabindex="0"><thead><tr><th>소스</th><th>표시 내용</th><th>필요 장치</th></tr></thead><tbody><tr><td><code>3D</code></td><td>로봇의 실시간 3D 자세(항상 표시)</td><td>—</td></tr><tr><td><code>전방</code> / <code>후방</code> / <code>좌측</code> / <code>우측</code></td><td>본체 카메라 한 대</td><td>해당 카메라</td></tr><tr><td><code>계단</code></td><td>전방·후방·하부 카메라를 합성한 계단 보행용 뷰</td><td>전방·후방·하부 카메라 4대 전부</td></tr><tr><td><code>4분할</code></td><td>본체 카메라 네 대를 2×2로 한 화면에</td><td>전방·후방·좌측·우측 카메라</td></tr><tr><td><code>파노라마</code></td><td>본체 카메라 네 대를 가로로 이어 붙인 뷰</td><td>전방·후방·좌측·우측 카메라</td></tr><tr><td><code>CCTV</code></td><td>옵션 PTZ 유닛의 컬러 카메라</td><td>PTZ 컬러 카메라(<a href="/RBQ/ko/manual/gui/ptz.html">PTZ 카메라</a> 참고)</td></tr><tr><td><code>열화상</code></td><td>PTZ 유닛의 열화상 카메라</td><td>PTZ 열화상 센서</td></tr><tr><td><code>PTZ 합성</code></td><td>컬러와 열화상의 합성</td><td>PTZ 컬러 카메라와 열화상 센서</td></tr><tr><td><code>SLAM</code></td><td>실시간 SLAM 맵</td><td>LiDAR</td></tr></tbody></table><p>영상은 16:9 비율을 유지한 채 상단 바 아래 공간에 맞춰 들어갑니다. 넓은 화면에서는 남는 좌우 여백에 카드와 가상 조이스틱이 놓입니다. 소스 목록은 상단 바를 가리지 않으므로 메뉴가 열려 있어도 E-STOP을 누를 수 있습니다.</p><h2 id="보기-옵션-오른쪽-카드" tabindex="-1">보기 옵션 (오른쪽 카드) <a class="header-anchor" href="#보기-옵션-오른쪽-카드" aria-label="Permalink to &quot;보기 옵션 (오른쪽 카드)&quot;">​</a></h2><p>오른쪽 <code>관측</code> 카드에는 보고 듣는 기능이 모여 있습니다. 카드의 동그란 버튼을 탭하면 카드가 동그라미로 접히거나 다시 펼쳐집니다. 처음에는 펼쳐져 있으며, 앱이 마지막 상태를 기억합니다.</p><ul><li><code>비전</code> — <code>비전</code> 팝오버를 엽니다. <code>Point to Go</code> 스위치(아래 참고)와 <code>야간 모드</code>, <code>DOCK 스캔</code> 같은 비전 토글이 있습니다.</li></ul><table tabindex="0"><thead><tr><th>항목</th><th>동작</th></tr></thead><tbody><tr><td><code>야간 모드</code></td><td>저조도 촬영</td></tr><tr><td><code>스텔스</code></td><td>LED·표시등 소등</td></tr><tr><td><code>GUIDE</code></td><td>영상에 주행 가이드선</td></tr><tr><td><code>FACE</code></td><td>얼굴 검출 박스</td></tr><tr><td><code>DOCK 스캔</code></td><td>도킹 마커 탐색</td></tr><tr><td><code>높이맵</code></td><td>지형 고저 표시. 아래 <code>└ 경계선 강조</code>는 <code>높이맵</code>이 켜져 있을 때만 활성화됩니다</td></tr></tbody></table><ul><li><code>3D 씬</code> — <code>3D 씬 설정</code>을 엽니다. <code>3D</code> 소스를 보고 있을 때만 나타납니다.</li><li><code>오디오</code> — 워키토키를 엽니다(<a href="/RBQ/ko/manual/gui/audio.html">오디오</a> 참고).</li></ul><p><code>속도 HUD</code>, <code>Gyro 위젯</code>, <code>영상 해상도</code>는 <strong>앱 설정 › 앱 설정</strong>에 있습니다.</p><p><code>3D 씬 설정</code>에는 다음 항목이 있습니다.</p><ul><li><code>그리드</code> — Grid ON / Grid OFF와 미터 단위 격자 크기(<code>−</code> / <code>+</code> 또는 직접 입력).</li><li><code>씬 테마</code> — 배경색 프리셋.</li><li><code>카메라 거동</code> — <code>Top</code>, <code>Robot</code>, <code>3D</code> 카메라 추적 방식.</li><li><code>LiDAR (표시)</code> — 포인트 클라우드 <code>Off</code> / <code>On</code>.</li></ul><h2 id="탭-이동-p2g" tabindex="-1">탭 이동 (P2G) <a class="header-anchor" href="#탭-이동-p2g" aria-label="Permalink to &quot;탭 이동 (P2G)&quot;">​</a></h2><p><code>Point to Go</code>를 켠 상태에서 전방 카메라 영상의 바닥 한 지점을 탭하면 로봇이 그곳으로 걸어갑니다. 누르는 순간 조준 마커가 서고 <strong>손가락을 끌면 마커가 따라옵니다</strong>. 명령은 손가락을 뗀 자리로 전송되므로, 보낼 지점을 정확히 맞춘 뒤 떼면 됩니다. <strong>영상 밖으로 끌어서 떼면 아무것도 보내지 않습니다</strong> — 잘못 눌렀을 때 취소하는 방법입니다. 경로와 목표 지점은 로봇이 송출 영상에 직접 그려 보내므로, 앱의 마커는 순간적인 피드백일 뿐입니다.</p><p>탭 한 번으로 로봇이 움직이려면 아래 <strong>네 가지가 모두</strong> 맞아야 합니다.</p><ol><li><code>비전</code> 팝오버에서 <code>Point to Go</code>가 켜져 있어야 합니다. 켜진 동안에는 뷰포트에 파란 테두리가 생깁니다.</li><li>뷰포트 소스가 <code>전방</code>이어야 합니다. 탭 좌표를 전방 카메라 기준으로 읽기 때문에, 다른 소스에서는 스위치가 흐려지고 <code>전방 카메라 소스에서만 사용</code>으로 바뀝니다.</li><li>로봇이 서 있고 걸을 수 있는 상태여야 합니다. 앱은 이것을 확인하지 않고, 명령을 실행할지는 로봇이 판단합니다.</li><li><strong>영상에 보이는 바닥</strong>을 탭해야 합니다. 앱은 모든 탭을 그대로 보내지만, 로봇은 그 지점이 자기 눈에 보이는 바닥일 때만 걸어갑니다. 수평선이나 벽, 하늘을 탭하면 마커만 뜨고 아무 일도 일어나지 않습니다.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>Point to Go</code>가 켜져 있는 동안은 영상 영역 전체가 탭 대상입니다 — 실수로 건드려도 이동 명령이 나갑니다. 사용이 끝나면 바로 끄십시오.</p></div><h2 id="도킹-마커-오버레이" tabindex="-1">도킹 마커 오버레이 <a class="header-anchor" href="#도킹-마커-오버레이" aria-label="Permalink to &quot;도킹 마커 오버레이&quot;">​</a></h2><p><img src="'+a+'" alt="전방 카메라 위의 도킹 마커 오버레이"></p><p>로봇이 도킹 마커(ArUco)를 보면 영상 위에 <code>도킹 시작</code> 버튼이 뜹니다. <code>3D</code>와 <strong>전방</strong>·<strong>후방</strong>·<strong>계단</strong>을 비롯한 모든 카메라 소스에서 나옵니다. 마커를 찾은 카메라를 보고 있는 소스에서는 마커 자리에 상자를 그립니다. 그 밖의 소스에서는 화면 아래 가운데에 도킹 마커 그림이 뜨며, 이 그림을 눌러도 도킹이 시작됩니다.</p><p><code>비전</code> 팝오버의 <code>DOCK 스캔</code>은 로봇이 카메라 영상에서 마커를 검출하는 동작을 켜고 끕니다. 기본값은 켜짐입니다. 도킹이 진행되는 동안에는 이 토글과 상관없이 마커를 그립니다 — 그 결과를 보려고 여는 화면이기 때문입니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/ko/manual/gui/developer-mode.html#vision">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h2 id="dock-view" tabindex="-1">Dock View <a class="header-anchor" href="#dock-view" aria-label="Permalink to &quot;Dock View&quot;">​</a></h2><p><img src="'+i+'" alt="도킹 진행 중의 Dock View"></p><p>도킹을 시작하면 <strong>Dock View</strong>가 열립니다. 뷰포트가 도킹에 쓰는 카메라 세 대의 화면으로 바뀌고, 로봇이 무엇을 검출하고 있는지 보여 줍니다. 그래서 도킹이 되는 이유도, 안 되는 이유도 눈으로 확인할 수 있습니다.</p><p>화면을 닫아도 도킹은 계속됩니다. 진행 중에는 화면 위쪽에 도킹 배너가 남아 있고, 배너의 <code>눌러서 보기</code>를 누르면 다시 들어옵니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Dock View는 도킹하는 동안에만 있는 화면입니다.</strong> 도킹이 끝나고 4초가 지나면 배너가 사라지고, 실패로 끝난 뒤에는 배너가 아예 뜨지 않습니다. 그때부터는 이 화면으로 들어갈 방법이 없습니다. 도킹 과정은 진행되는 동안에 보시고, 다시 보려면 도킹을 다시 시작하십시오.</p></div><p>영상 띠는 세 칸입니다: <strong>FRONT</strong>, <strong>REAR</strong>, <strong>BOTTOM2</strong>(하방 적외선 카메라). 마커를 찾은 칸은 주황 테두리로 강조되고, 마커 자리에 상자와 좌표축을 그립니다. 칸 라벨에는 검출에 쓴 마커 ID가 함께 나오고, <strong>BOTTOM2</strong>에는 IR 프로젝터가 켜져 있는지도 표시됩니다.</p><p>띠 아래에는 다음이 있습니다.</p><ul><li><strong>진행 단계</strong> — <code>접근 1</code>, <code>접근 2</code>, <code>접근 3</code>, <code>착석</code>, <code>충전</code>. <code>충전</code>은 충전 전류가 확인돼야 켜집니다.</li><li><strong>상태</strong> — 지금 무엇을 하는지, 실패했다면 그 이유를 문장으로 보여 줍니다.</li><li><strong>검출 안내</strong> — 로봇이 마커를 계속 버릴 때 나옵니다. 예를 들어 <code>마커 검출 품질이 낮습니다</code> 처럼 나옵니다. 마커를 찾지 못해 끝난 경우에는 무엇을 하면 되는지도 함께 보여 줍니다.</li><li><strong>버튼</strong> — 도킹 중에는 <code>도킹 중단</code>, 충전 중에는 <code>도킹 해제</code>, 실패 뒤에는 <code>도킹 재개</code>, 재시도를 모두 쓴 뒤에는 <code>일으켜 세우기</code>가 나오고, <code>닫기</code>는 항상 있습니다.</li></ul><p><code>도킹 해제</code>와 <code>일으켜 세우기</code>는 앉아 있는 로봇을 일으키는 명령이라 길게 눌러야 합니다. 누르고 있으면 버튼이 왼쪽부터 차오르고, 끝까지 차오른 순간(약 1초) 명령이 나갑니다. 다 차기 전에 손을 떼면 아무 명령도 나가지 않습니다.</p><p>로봇이 스스로 다시 시도하는 동안에는 <code>자동 재시도 중</code>이 표시되고, 사람이 할 일은 없습니다.</p><p>도킹이 끝나면 3초 뒤 배터리 잔량이 나옵니다. 그리고 5초가 지나면 카메라 화면이 자동으로 꺼지고 띠에 <code>도킹이 끝나 카메라 화면을 껐습니다</code>가 표시됩니다. 도킹한 로봇은 몇 시간씩 그대로 있으므로 영상이 필요 없기 때문입니다.</p><p><img src="'+l+'" alt="카메라 화면을 끈 뒤의 Dock View"></p>',37)])])}const D=t(n,[["render",s]]);export{b as __pageData,D as default};
